const body = $input.first().json.body || $input.first().json;
const camera = body.camera || "Unknown";
const timestamp = body.timestamp || "";
const photo_b64 = body.photo_base64 || "";

if (!photo_b64) return [{json: {status: "no_photo"}}];

// Coral detect
let objects = [];
try {
  const result = await this.helpers.httpRequest({
    method: "POST",
    url: "http://127.0.0.1:8090/detect_b64?lang=ru&threshold=0.3",
    body: JSON.stringify({image: photo_b64}),
    headers: {"Content-Type": "application/json"},
    timeout: 15000,
  });
  const parsed = typeof result === "string" ? JSON.parse(result) : result;
  objects = (parsed.objects || []).filter(o => o.score > 0.3);
} catch (e) {
  return [{json: {status: "coral_error", error: e.message}}];
}

// Only persons
const persons = objects.filter(o => o.label_en === "person" || o.label === "человек");
if (persons.length === 0) return [{json: {status: "no_person"}}];

const ts = (timestamp.split(" ")[1]) || timestamp;
const caption = "🚨 " + camera + " [" + ts + "]\nОбнаружен человек!";

// Telegram via emo-ai
try {
  const tgResult = await this.helpers.httpRequest({
    method: "POST",
    url: "http://127.0.0.1:9090/telegram",
    body: JSON.stringify({photo_base64: photo_b64, caption: caption}),
    headers: {"Content-Type": "application/json"},
    timeout: 20000,
  });
} catch (e) {
  return [{json: {status: "tg_error", error: e.message, caption}}];
}

return [{json: {status: "sent", camera, caption}}];
